window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[233]={"id":"233","numero":233,"titre":"Valvulopathies","objectifs":[{"id":"233-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l’insuffisance mitrale (IM), du rétrécissement aortique (RA) et de l’insuffisance aortique (IA)","contenu":"<div class=\"notion-course\"><p>Une <span>valvulopathie</span> est une atteinte d'une valve cardiaque réalisant soit un <span>obstacle</span> au passage du sang (<strong>rétrécissement</strong> = sténose), soit un <span>défaut d'étanchéité</span> avec reflux (<strong>insuffisance</strong> = régurgitation = fuite). Les quatre valvulopathies du cœur gauche à connaître sont le RA, l'IA, l'IM et le RM.</p>\n      <table>\n        <thead>\n          <tr><th>Valvulopathie</th><th>Définition</th><th>Fréquence</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>RA</strong> — rétrécissement aortique</td>\n            <td><span>Obstacle à l'éjection du ventricule gauche</span>, localisé le plus souvent au niveau de la valve aortique</td>\n            <td><span><span class=\"nc-yellow_bg\">Valvulopathie la plus fréquente</span></span></td>\n          </tr>\n          <tr>\n            <td><strong>IA</strong> — insuffisance aortique</td>\n            <td><span>Reflux (régurgitation) de sang de l'aorte vers le ventricule gauche en diastole</span> ; la racine aortique comme la valve peuvent être en cause</td>\n            <td>Valvulopathie peu fréquente, <span>prévalence</span> <span>↑ avec l'âge</span></td>\n          </tr>\n          <tr>\n            <td><strong>IM</strong> — insuffisance mitrale</td>\n            <td><span>Défaut d'étanchéité de la valve mitrale entraînant un reflux du VG vers l'oreillette gauche en systole</span></td>\n            <td><span>2ᵉ valvulopathie</span> par ordre de fréquence après le RA</td>\n          </tr>\n          <tr>\n            <td><strong>RM</strong> — rétrécissement mitral</td>\n            <td><span>Limitation d'ouverture de la valve mitrale en diastole</span> réalisant un obstacle à l'écoulement du sang de l'OG vers le VG au remplissage</td>\n            <td>Devenu <span>rare</span> dans les pays industrialisés (origine surtout rhumatismale)</td>\n          </tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/233/anatomie-valves.png\" alt=\"Vue de la base du cœur montrant les quatre valves : aortique, mitrale, tricuspide et pulmonaire\" loading=\"lazy\">\n        <figcaption>Anatomie des quatre valves cardiaques en vue basale. La <span>valve aortique</span> est normalement <strong>tricuspide</strong> (3 cusps ou sigmoïdes) ; la <span>valve mitrale</span> comporte <strong>2 feuillets</strong> (antérieur, postérieur) reliés au myocarde par les cordages et les piliers. Source : fiche source EDN item 233.</figcaption>\n      </figure>\n      <p><strong>Repères anatomiques.</strong> La <span>valve aortique</span> : 3 cusps (antéro-droite, antéro-gauche, non coronaire) qui s'ouvrent passivement vers l'aorte au cours de l'éjection. La <span>racine aortique</span> comprend anneau, sinus de Valsalva, jonction sinotubulaire et aorte initiale. La <span>valve mitrale</span> : 2 feuillets (<span <span=\"\">&gt;1</span> antérieur, 1 postérieur en 3 segments), insérés sur l'anneau mitral fibreux et tenus côté ventriculaire par les <span>cordages</span>, eux-mêmes amarrés aux <span>piliers</span> (muscles papillaires, partie intégrante du myocarde VG).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 234 — <span>Insuffisance cardiaque</span> · 238 — Souffle cardiaque de l'enfant</em></p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181f4bfbbf6013763e2a0?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Valvulopathies (233)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418128bf18fa6fb1f6969b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Rétrécissement aortique</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181108907dc584bec5884?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance mitrale</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418193ad00c369c741af6e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance aortique</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181308062dedcd73a6d81?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Rétrécissement mitral</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-08-item-233-valvulopathies/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 233</a></li><li><a href=\"https://academic.oup.com/eurheartj/article/46/44/4635/8234488\" target=\"_blank\" rel=\"noopener noreferrer\">ESC/EACTS · Valvulopathies, 2025</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/aortic-valve-regurgitation","label":"Radiopaedia : Aortic valve regurgitation"},{"href":"https://radiopaedia.org/cases/asymmetric-hypertrophic-cardiomyopathy","label":"Radiopaedia : Asymmetric hypertrophic cardiomyopathy"},{"href":"https://radiopaedia.org/articles/mitral-valve-regurgitation","label":"Radiopaedia : Mitral valve regurgitation"},{"href":"https://radiopaedia.org/articles/aortic-valve-stenosis","label":"Radiopaedia : Aortic valve stenosis"}]},{"id":"233-2","rang":"B","rubrique":"Eléments physiopathologiques","titre":"Connaître les mécanismes et conséquences physiopathologiques de l’IM, l’IA et du RA","contenu":"<div class=\"notion-course\"><p>Le mécanisme d'adaptation du VG dépend de la nature de la surcharge imposée : surcharge de <strong>pression</strong> (RA) ou surcharge de <strong>volume</strong> (IA, IM). C'est ce qui détermine le type d'hypertrophie du VG.</p>\n      <table>\n        <thead>\n          <tr><th></th><th>RA</th><th>IA</th><th>IM</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Surcharge imposée au VG</strong></td>\n            <td>Surcharge de <span>pression</span> (obstacle à l'éjection)</td>\n            <td>Surcharge <span>mixte</span> : volume (précharge ↑) + pression (postcharge ↑)</td>\n            <td>Surcharge de <span>volume</span> (le VES rétrograde vers l'OG <span class=\"nc-green_bg\">augmente</span> la précharge)</td>\n          </tr>\n          <tr>\n            <td><strong>Remodelage du VG</strong></td>\n            <td><span>Hypertrophie concentrique</span> (épaississement pariétal, loi de Laplace)</td>\n            <td><span>Hypertrophie <span class=\"nc-orange nc-bold\">excentrique</span></span> (dilatation + hypertrophie)</td>\n            <td><span>Hypertrophie <span class=\"nc-orange nc-bold\">excentrique</span></span> (dilatation du VG)</td>\n          </tr>\n          <tr>\n            <td><strong>Conséquence en amont</strong></td>\n            <td><span class=\"nc-yellow_bg\">Dysfonction diastolique</span> → <span>↑ pression capillaire pulmonaire</span></td>\n            <td>Élévation tardive des pressions de remplissage VG</td>\n            <td>Dilatation de l'OG, <span>HTP post-capillaire</span></td>\n          </tr>\n          <tr>\n            <td><strong><span>Évolution</span></strong></td>\n            <td>Longtemps <span class=\"nc-yellow_bg\">asymptomatique</span> (FEVG conservée), puis ↓ FEVG et signes d'IC</td>\n            <td>Longtemps bien tolérée, puis ↓ FEVG, IC d'effort puis de repos</td>\n            <td>Bien tolérée si progressive ; <span><span class=\"nc-red nc-bold\">fibrose</span></span> myocardique à terme</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">⚠️ Piège classique : opposer <span>hypertrophie concentrique</span> (réponse à une surcharge de <strong>pression</strong> — RA, <span>HTA</span>) et <span>hypertrophie <span class=\"nc-orange nc-bold\">excentrique</span></span> (réponse à une surcharge de <strong>volume</strong> ou à une <span class=\"nc-red nc-bold\">dilatation</span> — IA, IM, CMD).</div>\n      <p><strong>RA — détail.</strong> Le rétrécissement crée un <span><span class=\"nc-yellow_bg\">gradient de pression VG–aorte</span></span> ; le VG s'hypertrophie pour normaliser les contraintes pariétales (loi de Laplace) et garde longtemps une <span>FEVG normale</span>. À la phase <span class=\"nc-red nc-bold\">symptomatique</span> : ↓ compliance → <span><span class=\"nc-blue_bg\">dyspnée</span></span> (<span class=\"nc-blue nc-bold\">congestion pulmonaire</span>), ↑ consommation en O₂ → <span>angor</span>, dilatation et ↓ débit → <span><span class=\"nc-blue_bg\">syncope d'effort</span></span>. La <span>perte de la systole atriale lors d'un passage en FA</span> est en général mal tolérée (poussée d'IC).</p>\n      <p><strong>IA — détail.</strong> En amont : surcharge volumétrique (régurgitation <span class=\"nc-blue_bg\">diastolique</span>) + barométrique (↑ VES dans l'aorte). En aval : ↑ PAS et ↓ <span class=\"nc-yellow_bg\">PAD</span> → <span>↑ pression artérielle différentielle</span> (hyperpulsatilité) ; la baisse de la <span class=\"nc-yellow_bg\">PAD</span> <span class=\"nc-blue_bg\">diastolique</span> compromet la perfusion coronaire (<span><span class=\"nc-red nc-bold\">vol coronarien</span></span><span class=\"nc-red nc-bold\"> si IA sévère</span>). L'<span>IA aiguë</span> impose une surcharge volumétrique brutale à un VG non dilaté → élévation brutale des pressions → <span><span class=\"nc-red_bg\">OAP</span></span>.</p>\n      <p><strong>IM — détail.</strong> Le <span class=\"nc-red_bg\">VES est divisé en volume antérograde (vers l'aorte) et rétrograde (vers l'OG)</span> ; la compensation passe par l'activation du SRAA et du système sympathique. La <span class=\"nc-red nc-bold\">dilatation</span> de l'OG maintient une pression intra-atriale quasi normale mais favorise les <span>troubles du rythme atrial</span>. L'<span>IM aiguë</span> survient sur une OG non encore dilatée → <span>HTP immédiate</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 234 — <span>Insuffisance cardiaque</span></em></p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181f4bfbbf6013763e2a0?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Valvulopathies (233)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418128bf18fa6fb1f6969b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Rétrécissement aortique</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181108907dc584bec5884?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance mitrale</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418193ad00c369c741af6e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance aortique</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181308062dedcd73a6d81?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Rétrécissement mitral</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-08-item-233-valvulopathies/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 233</a></li><li><a href=\"https://academic.oup.com/eurheartj/article/46/44/4635/8234488\" target=\"_blank\" rel=\"noopener noreferrer\">ESC/EACTS · Valvulopathies, 2025</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":2},{"id":"233-3","rang":"A","rubrique":"Etiologies","titre":"Connaître les principales étiologies des valvulopathies (IM, RA, IA)","contenu":"<div class=\"notion-course\"><p>Objectif rang A à fort rendement EDN. À retenir : pour le RA le critère est <strong>l'âge</strong> ; pour l'IM la <span>classification</span> mécanistique de <span>Carpentier</span> ; pour l'IA le <span>terrain</span> (Marfan, bicuspidie, endocardite).</p>\n      <table>\n        <thead>\n          <tr><th>Valvulopathie</th><th>Étiologies principales</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>RA</strong></td>\n            <td>\n              <strong><span class=\"nc-red nc-bold\">&lt;</span><span><span class=\"nc-red nc-bold\"> 65-70 ans</span></span> :</strong> <span><span class=\"nc-orange_bg nc-bold\">bicuspidie aortique</span></span> (<span>1-2 %</span> de la population, <span>congénitale</span>, expose aussi à l'IA, l'EI, la <span class=\"nc-red nc-bold\">dilatation aortique</span>)<br>\n              <strong><span class=\"nc-blue nc-bold\">&gt;</span><span><span class=\"nc-blue nc-bold\"> 65-70 ans</span></span> :</strong> <span>RA <span class=\"nc-orange_bg\">dégénératif</span> (maladie de Mönckeberg)</span> — dépôts calciques, étiologie la plus fréquente<br>\n              <strong>Plus rare :</strong> <span>RA <span class=\"nc-orange_bg\">post-rhumatismal</span></span> (migrants ; souvent associé à IA + atteinte mitrale)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>IA</strong></td>\n            <td>\n              <strong>Valvulaire :</strong> <span><span class=\"nc-red_bg\">endocardite infectieuse</span></span> ; <span><span class=\"nc-blue_bg\">RAA</span></span> ; bicuspidie ; IA paraprothétique / intraprothétique<br>\n              <strong>Racine aortique :</strong> <span><span class=\"nc-red nc-bold\">dilatation</span> / maladie annulo-ectasiante</span> (<span><span class=\"nc-orange_bg\">maladie de Marfan</span></span>) ; <span><span class=\"nc-red nc-bold\">dissection aortique</span></span><br>\n              <strong>IA aiguë :</strong> <span class=\"nc-red_bg\">endocardite infectieuse</span> en premier lieu (destruction / <span class=\"nc-red_bg\">perforation</span> valvulaire, <span>abcès</span> de l'anneau)<br>\n              <strong>Causes rares (LiSA) :</strong> <span>syndrome d'Ehlers-Danlos</span>, <span>syndrome de Turner</span>, <span>syphilis tertiaire</span> (aortite), <span>anorexigènes</span> (fenfluramine, dexfenfluramine, benfluorex)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>IM</strong></td>\n            <td>\n              <strong>Organique :</strong> <span>IM <span class=\"nc-red nc-bold\">dystrophique</span></span> (<span class=\"nc-yellow_bg\">prolapsus</span>, <span><span class=\"nc-red_bg\">rupture</span></span><span class=\"nc-red_bg\"> de cordage</span> — <span class=\"nc-red nc-bold\">dégénérescence myxoïde ou fibroélastique</span>) ; <span>endocardite</span> ; <span><span class=\"nc-red nc-bold\">RAA</span></span><br>\n              <strong>Secondaire (fonctionnelle) :</strong> <span class=\"nc-red nc-bold\">dilatation de l'OG</span> (<span>FA</span>) ; <span>remodelage post-infarctus</span> du VG ; <span class=\"nc-blue_bg\">cardiomyopathie</span> dilatée<br>\n              <strong>IM aiguë :</strong> <span class=\"nc-red_bg\">rupture de cordage</span>, <span><span class=\"nc-red_bg\">rupture de pilier (IDM, traumatisme)</span></span>, endocardite\n            </td>\n          </tr>\n          <tr>\n            <td><strong>RM</strong></td>\n            <td>\n              <span><span class=\"nc-orange_bg\">Post-rhumatismal</span></span> (le plus fréquent — <span class=\"nc-yellow_bg\">fusion commissurale</span>) ; <span class=\"nc-orange_bg\">dégénératif</span> (anneau calcifié) ; <span><span class=\"nc-orange_bg\">congénital</span></span> (valve en parachute, rare)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong><span>Classification</span> de Carpentier (IM)</strong> — classe le mécanisme selon la position des feuillets en systole : <span>Type 1</span> mouvement valvulaire <span class=\"nc-green_bg\">normal</span> (<span class=\"nc-red_bg\">perforation</span>, <span class=\"nc-red nc-bold\">dilatation</span> de l'anneau) ; <span>Type 2</span> mouvement exagéré (<span class=\"nc-yellow_bg\">prolapsus</span>, <span><span class=\"nc-red_bg\">rupture</span></span><span class=\"nc-red_bg\"> de cordage</span>) ; <span>Type 3</span> mouvement restreint (3a en systole et diastole : <span class=\"nc-red nc-bold\">RAA</span>, <span><span class=\"nc-blue_bg\">radiothérapie</span></span>, <span class=\"nc-blue_bg\">médicaments</span> ; 3b en systole : cardiomyopathie <span>ischémique</span>).</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/233/carpentier.png\" alt=\"Classification de Carpentier de l&#x27;insuffisance mitrale en trois types selon le mouvement valvulaire\" loading=\"lazy\">\n        <figcaption>Classification de Carpentier de l'IM : Type 1 (mouvement normal), Type 2 (mouvement augmenté → prolapsus / rupture de cordage), Type 3 (mouvement restreint, sous-types 3a et 3b). Source : fiche source EDN item 233.</figcaption>\n      </figure>\n      <div class=\"callout callout-info\">⚠️ Piège classique : l'association <span><span class=\"nc-red_bg\">IM + RM</span></span> définit la « <strong><span class=\"nc-red_bg\">maladie mitrale</span></strong> » → toujours évoquer le <span><span class=\"nc-red_bg\">RAA</span></span>. De même, RA + IA = « <strong><span class=\"nc-red nc-bold\">maladie aortique</span></strong> ».</div>\n      <div class=\"callout callout-info\"><strong>Techniques chirurgicales de l'IM (LiSA).</strong> La <span>plastie mitrale</span> reste le traitement de référence quand elle est possible (résection quadrangulaire, néocordages, annuloplastie). La <span>technique d'Alfieri</span> (\"edge-to-edge\" ou bord-à-bord) suture le milieu des feuillets antérieur et postérieur pour transformer l'orifice en un double orifice — c'est le principe repris par le <span>MitraClip®</span> percutané chez les patients à haut risque chirurgical.</div>\n      <p><strong><span class=\"nc-red_bg\">Dégénérescence myxoïde</span> <span>vs</span> fibroélastique.</strong> La <span><span class=\"nc-red_bg\">dégénérescence myxoïde</span> (maladie de Barlow)</span> : <span class=\"nc-yellow_bg\">excès de tissu</span>, valves redondantes et épaissies, <span class=\"nc-yellow_bg\">prolapsus</span> — sujet <strong>jeune</strong>, plutôt <strong>femme</strong>. La <span><span class=\"nc-red_bg\">dégénérescence fibroélastique</span></span> : <span><span class=\"nc-red_bg\">rupture</span></span><span class=\"nc-red_bg\"> de cordage</span> sans <span class=\"nc-yellow_bg\">excès de tissu</span>, plus fréquente — sujet plus <strong>âgé</strong>, plutôt <strong>homme</strong>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 152 — <span class=\"nc-red_bg\">Endocardite infectieuse</span> · 339 — <span>Syndrome coronarien</span> aiguë</em></p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181f4bfbbf6013763e2a0?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Valvulopathies (233)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418128bf18fa6fb1f6969b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Rétrécissement aortique</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181108907dc584bec5884?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance mitrale</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418193ad00c369c741af6e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance aortique</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181308062dedcd73a6d81?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Rétrécissement mitral</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-08-item-233-valvulopathies/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 233</a></li><li><a href=\"https://academic.oup.com/eurheartj/article/46/44/4635/8234488\" target=\"_blank\" rel=\"noopener noreferrer\">ESC/EACTS · Valvulopathies, 2025</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":5},{"id":"233-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes fonctionnels et l’examen clinique (auscultation) de l’IM, RA et IA","contenu":"<div class=\"notion-course\"><p>Objectif <strong>très tombé à l'EDN</strong> (record d'étoiles de l'item). L'auscultation reste l'examen clé : chaque valvulopathie a une signature acoustique propre (temps, foyer, <span>irradiation</span>, timbre).</p>\n      <h4>Signes fonctionnels</h4>\n      <table>\n        <thead>\n          <tr><th>Valvulopathie</th><th>Signes fonctionnels</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>RA</strong></td><td>Longtemps <span class=\"nc-yellow_bg\">asymptomatique</span> ; à la phase <span class=\"nc-red nc-bold\">symptomatique</span> <span>triade <span class=\"nc-blue_bg\">angor d'effort</span> / <span class=\"nc-blue_bg\">syncope d'effort</span> / <span class=\"nc-blue_bg\">dyspnée d'effort</span></span> — leur apparition est de <span>mauvais pronostic</span></td></tr>\n          <tr><td><strong>IA</strong></td><td>Souvent <span class=\"nc-yellow_bg\">asymptomatique</span> ; <span><span class=\"nc-blue_bg\">dyspnée</span></span><span class=\"nc-blue_bg\"> d'effort</span> (NYHA), <span>angor</span> (rare, IA massive), <span><span class=\"nc-blue_bg\">asthénie</span></span>. Signes au repos = rares, tardifs, <span>mauvais pronostic</span></td></tr>\n          <tr><td><strong>IM</strong></td><td>Absents si IM modérée ; <span><span class=\"nc-blue_bg\">dyspnée</span></span><span class=\"nc-blue_bg\"> d'effort</span> d'installation lente, <span><span class=\"nc-blue_bg\">asthénie</span></span> ; tardivement <span>OAP</span>, <span><span class=\"nc-red_bg\">orthopnée</span></span>, <span><span class=\"nc-red_bg\">palpitations</span></span></td></tr>\n          <tr><td><strong>RM</strong></td><td>Longtemps <span class=\"nc-yellow_bg\">asymptomatique</span> ; <span><span class=\"nc-blue_bg\">dyspnée</span></span>, <span><span class=\"nc-blue_bg\">asthénie</span></span>, <span><span class=\"nc-blue_bg\">palpitations</span></span> ; révélé par une <span>grossesse</span> ou un passage en <span>FA</span> ; <span>hémoptysie</span></td></tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/233/auscultation-foyers.png\" alt=\"Schéma des quatre foyers d&#x27;auscultation cardiaque et de leur projection valvulaire\" loading=\"lazy\">\n        <figcaption>Les quatre foyers d'auscultation : aortique (2ᵉ EIC droit), pulmonaire (2ᵉ EIC gauche), tricuspide (4ᵉ EIC gauche), mitral (5ᵉ EIC gauche, ligne médioclaviculaire = apex). Source : fiche source EDN item 233.</figcaption>\n      </figure>\n      <h4>Auscultation comparée</h4>\n      <table>\n        <thead>\n          <tr><th></th><th>RA</th><th>IM</th><th>IA</th><th>RM</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Temps</strong></td>\n            <td><span><span class=\"nc-blue_bg\">Mésosystolique</span></span> (losangique)</td>\n            <td><span><span class=\"nc-blue_bg\">Holosystolique</span></span> (<span class=\"nc-blue_bg\">rectangulaire</span>)</td>\n            <td><span><span class=\"nc-blue nc-bold\">Proto-mésodiastolique</span> <span class=\"nc-blue nc-bold\">decrescendo</span></span> (<span class=\"nc-purple_bg\">triangulaire</span>)</td>\n            <td><span>Roulement <span class=\"nc-blue_bg\">diastolique</span></span></td>\n          </tr>\n          <tr>\n            <td><strong>Foyer / siège</strong></td>\n            <td>Foyer aortique (2ᵉ EIC droit)</td>\n            <td>Apexo-axillaire, maximal <span class=\"nc-green_bg\">à la pointe</span></td>\n            <td>Foyer aortique (2ᵉ EIC droit)</td>\n            <td><span class=\"nc-red nc-bold\">Pointe</span> (foyer mitral)</td>\n          </tr>\n          <tr>\n            <td><strong><span>Irradiation</span></strong></td>\n            <td>Vaisseaux du cou (carotides)</td>\n            <td><span class=\"nc-blue_bg\">Aisselle</span> (base du cœur si <span class=\"nc-yellow_bg\">prolapsus</span> postérieur)</td>\n            <td>Bord gauche du sternum</td>\n            <td>—</td>\n          </tr>\n          <tr>\n            <td><strong>Timbre</strong></td>\n            <td><span class=\"nc-blue_bg\">Rude</span>, <span class=\"nc-blue_bg\">râpeux</span></td>\n            <td><span class=\"nc-blue_bg\">Doux</span>, « <span class=\"nc-blue_bg\">jet de vapeur</span> » (parfois <span class=\"nc-blue_bg\">rude</span>, musical)</td>\n            <td><span class=\"nc-blue_bg\">Doux</span>, humé, aspiratif</td>\n            <td>—</td>\n          </tr>\n          <tr>\n            <td><strong>Position d'examen</strong></td>\n            <td>Assis penché en avant, expiration</td>\n            <td><span class=\"nc-pink_bg\">Décubitus latéral gauche</span></td>\n            <td>Assis penché en avant, bras levé</td>\n            <td><span class=\"nc-pink_bg\">Décubitus latéral gauche</span></td>\n          </tr>\n          <tr>\n            <td><strong>Bruits surajoutés</strong></td>\n            <td><span>B4</span> (<span>galop</span> présystolique)</td>\n            <td><span><span class=\"nc-yellow_bg nc-bold\">Click</span></span> méso ou télésystolique (<span class=\"nc-yellow_bg\">prolapsus</span>)</td>\n            <td><span><span class=\"nc-red nc-bold\">Pistol shot</span></span><span class=\"nc-red nc-bold\"> mésosystolique</span> ; <span><span class=\"nc-yellow_bg nc-bold\">click</span></span> protosystolique</td>\n            <td><span>Triade de Durozier</span> : éclat de B1 + claquement d'ouverture mitral + roulement <span class=\"nc-blue_bg\">diastolique</span></td>\n          </tr>\n          <tr>\n            <td><strong><span>Signes de gravité</span></strong></td>\n            <td><span><span class=\"nc-red nc-bold\">Abolition du B2</span></span> (RA serré calcifié) ; <span>B3</span> de <span>galop</span> ; souffle inaudible si bas débit</td>\n            <td><span>B3</span> ; éclat de B2 (HTAP) ; <span class=\"nc-red_bg\">roulement mésodiastolique</span> ; souffle d'IT fonctionnelle</td>\n            <td><span class=\"nc-red_bg\">Souffle </span><span><span class=\"nc-red_bg\">holodiastolique</span></span> ; <span>B3</span> ; <span class=\"nc-red_bg\">roulement de Flint apexien</span></td>\n            <td>Éclat de B2 au <span class=\"nc-brown_bg\">foyer pulmonaire</span> (HTAP)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">⚠️ Piège classique : <strong>PAS DE <span>B4</span> dans l'insuffisance mitrale</strong> (pas d'<span class=\"nc-yellow_bg\">HVG</span>). Le B4 (galop présystolique) appartient au RA. Ne pas confondre le <span>roulement de Flint</span> (IA sévère, RM fonctionnel) avec le <span class=\"nc-red_bg\">roulement mésodiastolique</span> de l'IM.</div>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/233/souffles-cardiaques-schema.png\" alt=\"Schéma chronologique des souffles des quatre valvulopathies par rapport aux bruits B1 et B2\" loading=\"lazy\">\n        <figcaption>Chronologie des souffles : RA mésosystolique losangique, IM holosystolique rectangulaire, IA diastolique decrescendo, RM roulement diastolique. Repères B1/B2/<span>B3</span>/B4. Source : fiche source EDN item 233.</figcaption>\n      </figure>\n      <h4>Les bruits du cœur</h4>\n      <table>\n        <thead>\n          <tr><th>Bruit</th><th>Signification</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>B1</strong></td><td>Début de la systole — fermeture des valves auriculo-ventriculaires (mitrale et tricuspide), maximal à l'apex</td></tr>\n          <tr><td><strong>B2</strong></td><td>Début de la diastole — fermeture des valves aortique et pulmonaire</td></tr>\n          <tr><td><strong><span>B3</span></strong></td><td>Protodiastolique — <span><span class=\"nc-red nc-bold\">dysfonction systolique</span></span> (<span>galop</span> protodiastolique) ; physiologique chez l'enfant / l'adulte jeune</td></tr>\n          <tr><td><strong><span>B4</span></strong></td><td>Télédiastolique (contraction atriale) — <span><span class=\"nc-yellow_bg\">dysfonction diastolique</span></span> (HVG, FEVG préservée)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Modifications des bruits à connaître :</strong> <span class=\"nc-red nc-bold\">abolition du B2</span> = <span>RA serré</span> ; éclat du B2 = <span>HTAP</span> ; dédoublement large et fixe du B2 = <span>CIA</span> ; diminution du B1 = <span>IM</span> ; éclat du B1 = <span>RM</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 238 — Souffle cardiaque de l'enfant</em></p><h4>Points de raisonnement et précautions</h4><ul><li>L’intensité du souffle ne quantifie pas à elle seule la sévérité : une fuite aiguë sévère ou un RA à bas débit peut être peu bruyant. Toute <span class=\"nc-blue_bg\">dyspnée</span> aiguë avec souffle nouveau impose une échographie rapide.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181f4bfbbf6013763e2a0?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Valvulopathies (233)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418128bf18fa6fb1f6969b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Rétrécissement aortique</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181108907dc584bec5884?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance mitrale</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418193ad00c369c741af6e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance aortique</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181308062dedcd73a6d81?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Rétrécissement mitral</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-08-item-233-valvulopathies/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 233</a></li><li><a href=\"https://academic.oup.com/eurheartj/article/46/44/4635/8234488\" target=\"_blank\" rel=\"noopener noreferrer\">ESC/EACTS · Valvulopathies, 2025</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":16},{"id":"233-5","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître l’intérêt de l’électrocardiogramme (ECG), de la radiographie thoracique, de l’épreuve d’effort dans les valvulopathies","contenu":"<div class=\"notion-course\"><p>L'<span>ECG</span> et la <span>radiographie thoracique</span> sont des examens de <strong><span class=\"nc-red nc-bold\">retentissement</span></strong> : ils ne font pas le diagnostic (c'est l'<span>échographie</span>) mais évaluent l'<span>évolution</span>. L'<span>épreuve d'effort</span> a une place très ciblée.</p>\n      <table>\n        <thead>\n          <tr><th>Valvulopathie</th><th><span>ECG</span></th><th><span>Radiographie</span> thoracique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>RA</strong></td>\n            <td><span><span class=\"nc-orange_bg\">HVG</span></span><span class=\"nc-orange_bg\"> de type systolique</span> (T négatives précordiales gauches) ; HAG ; troubles de <span>conduction</span> (BBG, BAV 1) ; FA si RA évolué</td>\n            <td>Normale, ou dilatation du VG (<span><span class=\"nc-blue_bg\">cardiomégalie</span></span>) et <span><span class=\"nc-blue_bg\">surcharge pulmonaire</span></span> si RA évolué</td>\n          </tr>\n          <tr>\n            <td><strong>IA</strong></td>\n            <td><span>HVG</span> <span class=\"nc-blue_bg\">diastolique</span> (ondes R amples, T positives précordiales gauches) ; <span>FA ou <span class=\"nc-orange nc-bold\">ESV</span> = mauvais pronostic</span></td>\n            <td>↑ <span>index cardiothoracique</span> si IA volumineuse chronique ; <span>débord aortique</span> (arc moyen droit) si aorte déroulée</td>\n          </tr>\n          <tr>\n            <td><strong>IM</strong></td>\n            <td><span>HAG</span>, <span class=\"nc-yellow_bg\">HVG</span> ; <span>FA</span> ; <span>HVD</span> des IM évoluées avec HTAP</td>\n            <td><span><span class=\"nc-blue_bg\">Cardiomégalie</span></span> (<span class=\"nc-brown_bg\">dilatation VG</span>) ; dilatation de l'OG (<span><span class=\"nc-red nc-bold\">arc moyen gauche convexe</span></span>, débord de l'arc inférieur droit) ; signes d'HTAP</td>\n          </tr>\n          <tr>\n            <td><strong>RM</strong></td>\n            <td><span>HAG</span> ; <span>HVD</span></td>\n            <td><span><span class=\"nc-blue_bg\">Surcharge pulmonaire</span></span> ; <span><span class=\"nc-blue_bg\">cardiomégalie</span></span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">⚠️ <span>Urgence</span> à connaître : l'<span>épreuve d'effort est contre-indiquée dans le RA <span class=\"nc-red nc-bold\">symptomatique</span></span>. Elle est en revanche <strong>préconisée dans le RA serré <span class=\"nc-yellow_bg\">asymptomatique</span></strong> pour objectiver le caractère réellement <span class=\"nc-yellow_bg\">asymptomatique</span> (certains patients sous-estiment leurs <span class=\"nc-red nc-bold\">symptômes</span> en limitant leurs efforts) et dépister une chute de la PA à l'effort.</div>\n      <p><strong><span>Épreuve d'effort</span> — points clés.</strong> Dans le RA serré asymptomatique : recherche d'une augmentation inadéquate ou d'une baisse de la PA à l'effort, et démasquage de <span class=\"nc-red nc-bold\">symptômes</span>. Dans l'IA : <span>non indiquée selon le LiSA</span>, mais peut aider à la décision en appréciant la tolérance fonctionnelle.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 232 — <span><span class=\"nc-blue_bg\">Fibrillation</span></span><span class=\"nc-blue_bg\"> atriale</span></em></p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181f4bfbbf6013763e2a0?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Valvulopathies (233)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418128bf18fa6fb1f6969b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Rétrécissement aortique</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181108907dc584bec5884?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance mitrale</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418193ad00c369c741af6e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance aortique</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181308062dedcd73a6d81?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Rétrécissement mitral</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-08-item-233-valvulopathies/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 233</a></li><li><a href=\"https://academic.oup.com/eurheartj/article/46/44/4635/8234488\" target=\"_blank\" rel=\"noopener noreferrer\">ESC/EACTS · Valvulopathies, 2025</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":0},{"id":"233-6","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître la valeur primordiale de l’échocardiographie dans l’IM, l’IA et le RA","contenu":"<div class=\"notion-course\"><ul><li>L’ETT Doppler est l’examen central : valve et mécanisme, sévérité intégrée, ventricules, oreillettes, pressions pulmonaires et aorte. L’ETO complète une mauvaise fenêtre, une suspicion d’endocardite ou la planification d’un geste.</li><li>RA sévère à haut gradient : Vmax ≥ 4 m/s, gradient moyen ≥ 40 mmHg, surface généralement ≤ 1 cm² (≤ 0,6 cm²/m² indexée). Vérifier la concordance et les mesures ; un petit orifice avec faible gradient n’est pas automatiquement un RA sévère.</li><li>RA bas débit/bas gradient : examiner volume d’éjection indexé, FEVG, PA et erreurs de mesure ; dobutamine dans certaines formes à FEVG réduite, score calcique valvulaire au scanner selon contexte. Un bas débit peut exister malgré une FEVG préservée.</li><li>IM : évaluation multiparamétrique (morphologie, vena contracta, flux, volume et surface régurgitants, retentissement). Repères classiques d’IM primaire sévère : surface régurgitante ≥ 40 mm², <span class=\"nc-blue_bg\">volume régurgité</span> ≥ 60 mL ; des seuils plus faibles peuvent être pertinents dans l’IM secondaire à bas débit. Ne pas appliquer 30 mm²/45 mL à toute IM.</li><li>IA : mécanisme valvulaire ou aortique, jet, vena contracta, reflux <span class=\"nc-red nc-bold\">holodiastolique</span> dans l’aorte descendante et quantification intégrée ; mesurer VG, FEVG et aorte.</li><li>RM : surface mitrale et gradient interprétés avec fréquence et débit ; une surface ≤ 1,5 cm² définit une sténose cliniquement significative. Un gradient isolé ne suffit pas.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181f4bfbbf6013763e2a0?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Valvulopathies (233)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418128bf18fa6fb1f6969b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Rétrécissement aortique</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181108907dc584bec5884?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance mitrale</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418193ad00c369c741af6e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance aortique</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181308062dedcd73a6d81?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Rétrécissement mitral</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-08-item-233-valvulopathies/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 233</a></li><li><a href=\"https://academic.oup.com/eurheartj/article/46/44/4635/8234488\" target=\"_blank\" rel=\"noopener noreferrer\">ESC/EACTS · Valvulopathies, 2025</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":5},{"id":"233-7","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les évolutions et complications de l’IM, du RA et de l’IA","contenu":"<div class=\"notion-course\"><p>Toutes les valvulopathies gauches chroniques sont longtemps bien tolérées ; <strong>l'apparition de <span class=\"nc-red nc-bold\">symptômes</span> signe un tournant pronostique</strong>. Les formes aiguës sont d'emblée des urgences.</p>\n      <table>\n        <thead>\n          <tr><th>Valvulopathie</th><th>Complications</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>RA</strong></td>\n            <td>\n              <strong>Cardiaques :</strong> <span>insuffisance cardiaque</span> ; <span>FA</span> (mal tolérée — perte de la systole atriale) ; troubles de conduction<br>\n              <strong>Graves :</strong> <span><span class=\"nc-orange_bg\">mort subite</span></span> (surtout RA serré <span class=\"nc-red nc-bold\">symptomatique</span>) ; <span class=\"nc-orange_bg\">endocardite</span> (rare) ; <span class=\"nc-orange_bg\">embolies calcaires systémiques</span><br>\n              <strong>Particulière :</strong> <span><span class=\"nc-orange_bg\">syndrome de Heyde</span></span> — anémie ferriprive par hémorragie digestive (<span class=\"nc-blue nc-bold\">angiodysplasies intestinales</span>) + <span class=\"nc-blue nc-bold\">anomalie </span><span><span class=\"nc-blue nc-bold\">acquise</span></span><span class=\"nc-blue nc-bold\"> du facteur Von Willebrand</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>IA</strong></td>\n            <td>\n              <strong>Infectieuse :</strong> <span><span class=\"nc-red_bg\">endocardite infectieuse</span></span><br>\n              <strong>Cardiaque :</strong> <span>insuffisance cardiaque</span> gauche ou globale, tardive<br>\n              <strong>Aortique :</strong> <span><span class=\"nc-red_bg\">dissection ou rupture aortique</span></span> si <span class=\"nc-red nc-bold\">dilatation</span> de l'aorte<br>\n              <strong>Rythmique :</strong> <span><span class=\"nc-red_bg\">mort subite</span></span> (rare — <span class=\"nc-red nc-bold\">trouble du rythme</span>, <span><span class=\"nc-red nc-bold\">rupture</span></span><span class=\"nc-red nc-bold\"> aortique</span>)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>IM</strong></td>\n            <td>\n              <strong>Cardiaque :</strong> <span>insuffisance cardiaque</span> (tardive si chronique, rapide si aiguë)<br>\n              <strong>Mécanique :</strong> <span><span class=\"nc-red_bg\">rupture</span></span><span class=\"nc-red_bg\"> de cordage</span> (IM <span class=\"nc-red nc-bold\">dystrophique</span> par <span class=\"nc-yellow_bg\">prolapsus</span>)<br>\n              <strong>Infectieuse :</strong> <span class=\"nc-red_bg\">endocardite infectieuse</span><br>\n              <strong>Rythmique :</strong> <span>FA / flutter</span> ; <span class=\"nc-red_bg\">troubles du rythme ventriculaire</span> (disjonction annulaire du <span class=\"nc-yellow_bg\">prolapsus</span> / maladie de Barlow → <span><span class=\"nc-red_bg\">mort subite</span></span> exceptionnelle)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>RM</strong></td>\n            <td><span>FA</span> ; <span><span class=\"nc-red nc-bold\">insuffisance cardiaque</span></span> ; <span class=\"nc-red nc-bold\">HTAP</span> ; <span>complications thromboemboliques</span> ; <span>décompensation</span> lors d'une <span>grossesse</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">⚠️ <span>Urgence</span> : l'<span>IM aiguë</span> (<span><span class=\"nc-red nc-bold\">rupture</span></span><span class=\"nc-red nc-bold\"> de cordage</span> / pilier, <span class=\"nc-orange_bg\">endocardite</span>) et l'<span>IA aiguë</span> (<span class=\"nc-orange_bg\">endocardite</span>, <span>dissection</span>) sont <span class=\"nc-red nc-bold\">mal tolérées</span> → <span><span class=\"nc-red nc-bold\">OAP</span></span>, <span>état de choc</span>, risque de <span><span class=\"nc-orange_bg\">mort subite</span></span>. <span><span class=\"nc-pink_bg\">Chirurgie</span></span> souvent urgente.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 152 — <span class=\"nc-red_bg\">Endocardite infectieuse</span> · 232 — <span><span class=\"nc-blue_bg\">Fibrillation</span></span><span class=\"nc-blue_bg\"> atriale</span> · 234 — <span>Insuffisance cardiaque</span> · 332 — Etat de <span>choc</span></em></p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181f4bfbbf6013763e2a0?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Valvulopathies (233)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418128bf18fa6fb1f6969b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Rétrécissement aortique</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181108907dc584bec5884?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance mitrale</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418193ad00c369c741af6e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance aortique</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181308062dedcd73a6d81?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Rétrécissement mitral</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-08-item-233-valvulopathies/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 233</a></li><li><a href=\"https://academic.oup.com/eurheartj/article/46/44/4635/8234488\" target=\"_blank\" rel=\"noopener noreferrer\">ESC/EACTS · Valvulopathies, 2025</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":0},{"id":"233-8","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes du traitement chirurgical de l’IM, du RA et de l’IA","contenu":"<div class=\"notion-course\"><p>Le traitement curatif d'une valvulopathie est mécanique (chirurgical ou percutané) : il n'existe pas de <span class=\"nc-pink_bg\">traitement médical</span> capable de corriger la <span>lésion</span>. Principes par valvulopathie :</p>\n      <table>\n        <thead>\n          <tr><th>Valvulopathie</th><th>Principe chirurgical</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>RA</strong></td><td><span><span class=\"nc-pink_bg\">Remplacement valvulaire</span> aortique</span> — seul traitement du RA (prothèse mécanique ou <span>biologique</span>)</td></tr>\n          <tr><td><strong>IA</strong></td><td><span><span class=\"nc-pink_bg\">Remplacement valvulaire</span> aortique</span> simple ; + remplacement de l'aorte ascendante si <span class=\"nc-red nc-bold\">dilatation</span> (<span>intervention de Bentall</span> : <span class=\"nc-pink\">tube prothétique avec réimplantation des coronaires</span>)</td></tr>\n          <tr><td><strong>IM</strong></td><td>Une plastie ou une bioprothèse n’impose pas à elle seule une anticoagulation à vie ; une FA ou une autre indication peut toutefois la rendre nécessaire.</td></tr>\n          <tr><td><strong>RM</strong></td><td><span><span class=\"nc-pink nc-bold\">Remplacement valvulaire mitral</span></span> ; commissurotomie chirurgicale (post-rhumatismale, devenue rare)</td></tr>\n        </tbody>\n      </table>\n      <table>\n        <thead>\n          <tr><th></th><th>Prothèse mécanique</th><th>Prothèse <span>biologique</span></th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Anticoagulation</strong></td><td><span>Anticoagulant (AVK) à vie</span></td><td>Évite l'<span>anticoagulation</span> au long cours</td></tr>\n          <tr><td><strong>Durée de vie</strong></td><td>Longue durée</td><td>Risque de <span>dégénérescence en 10-15 ans</span></td></tr>\n          <tr><td><strong>Indication préférentielle</strong></td><td>Sujet <span>jeune</span> (ou <span>anticoagulation</span> déjà nécessaire — FA)</td><td>Patient âgé (&gt;<span> 65-70 ans</span>), <span class=\"nc-orange_bg\">désir de </span><span><span class=\"nc-orange_bg\">grossesse</span></span>, CI aux <span>anticoagulants</span></td></tr>\n        </tbody>\n      </table>\n      <p>Rechercher et traiter les foyers infectieux, notamment dentaires, avant une intervention programmée ; les examens ORL, respiratoires et vasculaires sont guidés par le contexte plutôt qu’imposés à tous.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 153 — <span>Surveillance</span> valve et prothèse vasculaire</em></p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181f4bfbbf6013763e2a0?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Valvulopathies (233)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418128bf18fa6fb1f6969b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Rétrécissement aortique</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181108907dc584bec5884?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance mitrale</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418193ad00c369c741af6e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance aortique</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181308062dedcd73a6d81?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Rétrécissement mitral</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-08-item-233-valvulopathies/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 233</a></li><li><a href=\"https://academic.oup.com/eurheartj/article/46/44/4635/8234488\" target=\"_blank\" rel=\"noopener noreferrer\">ESC/EACTS · Valvulopathies, 2025</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":0},{"id":"233-9","rang":"B","rubrique":"Prise en charge","titre":"Connaître le principe des traitements percutanés de l’IM, du RA","contenu":"<div class=\"notion-course\"><p>Les traitements percutanés évitent la sternotomie et la circulation extracorporelle : ils s'adressent surtout aux patients âgés ou à risque chirurgical.</p>\n      <table>\n        <thead>\n          <tr><th>Technique</th><th>Principe</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>TAVI</strong> (RA)<br><em>transcatheter aortic valve implantation</em></td>\n            <td>Implantation par voie percutanée d'une <span>valve biologique</span> au sein de la valve aortique pathologique <strong>laissée en place</strong> ; <span>voie fémorale</span> le plus souvent (ou apicale, carotidienne) ; anesthésie locale</td>\n          </tr>\n          <tr>\n            <td><strong>Réparation bord à bord</strong> (IM)<br><em>type <span>MitraClip</span></em></td>\n            <td>Mise en place par voie percutanée d'un <span>clip</span> rapprochant les feuillets mitraux antérieur et postérieur, corrigeant la fuite</td>\n          </tr>\n          <tr>\n            <td><strong>Valvuloplastie aortique au ballon</strong> (RA)</td>\n            <td><span class=\"nc-red nc-bold\">Dilatation</span> simple du RA par un ballon, sans prothèse — <span>quasiment abandonnée</span> depuis le TAVI (taux élevé de resténose précoce)</td>\n          </tr>\n          <tr>\n            <td><strong><span>Commissurotomie mitrale percutanée</span></strong> (RM)</td>\n            <td>Ouverture des commissures fusionnées par ballon, dans le RM rhumatismal à anatomie favorable</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">⚠️ Le <strong>TAVI</strong> expose à des complications spécifiques : hématome au point de <span>ponction</span>, fuite paravalvulaire résiduelle (mauvaise implantation), <span>lésions du tissu de conduction</span> (<span>~30 %</span> nécessitent un <span>pacemaker</span>), <span>AVC ischémique</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 153 — <span>Surveillance</span> valve et prothèse vasculaire</em></p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181f4bfbbf6013763e2a0?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Valvulopathies (233)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418128bf18fa6fb1f6969b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Rétrécissement aortique</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181108907dc584bec5884?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance mitrale</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418193ad00c369c741af6e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance aortique</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181308062dedcd73a6d81?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Rétrécissement mitral</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-08-item-233-valvulopathies/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 233</a></li><li><a href=\"https://academic.oup.com/eurheartj/article/46/44/4635/8234488\" target=\"_blank\" rel=\"noopener noreferrer\">ESC/EACTS · Valvulopathies, 2025</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":1},{"id":"233-10","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principales indications de traitement chirurgical de l’IM, du RA et de l’IA","contenu":"<div class=\"notion-course\"><ul><li>Décision en équipe valvulaire : sévérité confirmée, symptômes, fonction/dimensions ventriculaires, risque, anatomie, espérance de vie et préférence du patient.</li><li>RA <span class=\"nc-yellow_bg\">sévère symptomatique</span> : <span class=\"nc-pink_bg\">remplacement valvulaire</span> sauf absence de bénéfice attendu ; la voie dépend de la Heart Team. Si apparemment <span class=\"nc-yellow_bg\">asymptomatique</span> : test d’effort encadré si indiqué, FEVG, progression, sévérité et marqueurs pronostiques ; certaines situations justifient une intervention précoce.</li><li>IA sévère : <span class=\"nc-red nc-bold\">symptômes</span> ou <span class=\"nc-red nc-bold\">retentissement</span> VG justifient l’intervention. Repères classiques chez l’<span class=\"nc-yellow_bg\">asymptomatique</span> : <span class=\"nc-red nc-bold\">FEVG ≤ 50 %</span>, diamètre télésystolique <span class=\"nc-red nc-bold\">&gt; 50 mm</span> ou <span class=\"nc-red nc-bold\">&gt; 25 mm/m²</span>. Des critères plus précoces peuvent être discutés dans les recommandations récentes, surtout à faible risque opératoire.</li><li>IM primaire sévère : réparation durable privilégiée si possible. Repères de dysfonction : FEVG ≤ 60 % ou diamètre télésystolique ≥ 40 mm ; une <span class=\"nc-red nc-bold\">rupture de cordage</span> n’est pas nécessaire pour utiliser ces seuils. FA, hypertension pulmonaire et <span class=\"nc-red nc-bold\">dilatation</span> de l’OG peuvent également conduire à une intervention sélectionnée.</li><li>IM secondaire : optimiser d’abord traitement de l’insuffisance cardiaque et resynchronisation si indiquée, puis discuter réparation percutanée ou <span class=\"nc-pink_bg\">chirurgie</span> selon profil ; ne pas appliquer automatiquement les indications d’IM primaire.</li><li>IA ou IM aiguë mal tolérée : urgence spécialisée, souvent chirurgicale. Aortopathie : seuils propres à l’étiologie, taille corporelle, croissance et contexte familial ; ne pas utiliser 55 mm pour toutes les maladies génétiques.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181f4bfbbf6013763e2a0?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Valvulopathies (233)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418128bf18fa6fb1f6969b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Rétrécissement aortique</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181108907dc584bec5884?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance mitrale</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418193ad00c369c741af6e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance aortique</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181308062dedcd73a6d81?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Rétrécissement mitral</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-08-item-233-valvulopathies/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 233</a></li><li><a href=\"https://academic.oup.com/eurheartj/article/46/44/4635/8234488\" target=\"_blank\" rel=\"noopener noreferrer\">ESC/EACTS · Valvulopathies, 2025</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":2},{"id":"233-11","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principales indications du traitement percutané du RA et de l’IM","contenu":"<div class=\"notion-course\"><ul><li>TAVI ou <span class=\"nc-pink_bg\">chirurgie</span> : décision partagée en Heart Team tenant compte de l’âge, de la durabilité, de l’anatomie valvulaire/aortique et vasculaire, des coronaires et des gestes associés.</li><li>Actualisation ESC/EACTS 2025 : TAVI recommandé à partir de 70 ans pour une sténose aortique tricuspide avec anatomie adaptée ; chirurgie privilégiée chez le patient plus jeune à faible risque. Les autres cas sont individualisés. Le seuil de 75 ans correspond à des recommandations antérieures.</li><li>Réparation mitrale bord à bord (TEER) : IM primaire <span class=\"nc-yellow_bg\">sévère symptomatique</span> à haut risque chirurgical avec anatomie favorable, ou IM secondaire sélectionnée malgré traitement optimal ; vérifier les critères et le bénéfice attendu.</li><li>Commissurotomie mitrale percutanée : RM rhumatismal sélectionné, valve adaptée, sans thrombus atrial ni IM significative ; l’ETO est importante avant le geste.</li><li>Valvuloplastie aortique au ballon : rôle de pont dans certaines urgences ou situations particulières, sans durabilité équivalente à un remplacement.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181f4bfbbf6013763e2a0?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Valvulopathies (233)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418128bf18fa6fb1f6969b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Rétrécissement aortique</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181108907dc584bec5884?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance mitrale</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418193ad00c369c741af6e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance aortique</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181308062dedcd73a6d81?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Rétrécissement mitral</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-08-item-233-valvulopathies/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 233</a></li><li><a href=\"https://academic.oup.com/eurheartj/article/46/44/4635/8234488\" target=\"_blank\" rel=\"noopener noreferrer\">ESC/EACTS · Valvulopathies, 2025</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":0},{"id":"233-12","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités du traitement médical de l’IA","contenu":"<div class=\"notion-course\"><div class=\"callout callout-info\">⚠️ À retenir : <strong>aucun traitement <span>médicamenteux</span> spécifique n'a démontré de bénéfice dans l'IA</strong>. En particulier, pas d'<span>IEC</span> en l'absence d'<span><span class=\"nc-red_bg\">insuffisance cardiaque</span></span> congestive. Le traitement curatif de l'IA reste mécanique (<span><span class=\"nc-pink_bg\">chirurgie</span></span>).</div>\n      <p>Le <span class=\"nc-pink_bg\">traitement médical</span> de l'IA se limite à des situations précises :</p>\n      <ul>\n        <li><strong>IA sévère compliquée d'IC congestive :</strong> <span class=\"nc-pink_bg\">traitement médical</span> (<span>diurétiques</span>, éventuellement <span>IEC</span>) <em>dans l'attente de la <span>chirurgie</span></em> — la résolution des signes d'IC sous traitement ne doit pas faire repousser la chirurgie.</li>\n        <li><strong><span>Syndrome de <span class=\"nc-yellow_bg\">Marfan</span></span> / <span class=\"nc-red nc-bold\">dilatation</span> de l'aorte :</strong> <span><span class=\"nc-pink nc-bold\">bêtabloquants</span></span> = traitement validé pour protéger l'aorte ; <span><span class=\"nc-pink nc-bold\">ARA2</span></span> uniquement en cas d'<span>intolérance</span> aux <span><span class=\"nc-pink nc-bold\">bêtabloquants</span></span>.</li>\n        <li><strong>Activité physique :</strong> sport de compétition <span>contre-indiqué si IA sévère</span> ; sport de loisir en endurance encouragé à un niveau modéré.</li>\n      </ul>\n      <p><strong>Prophylaxie de l'<span class=\"nc-red_bg\">endocardite infectieuse</span>.</strong> Bonne <span><span class=\"nc-green nc-bold\">hygiène bucco-dentaire</span></span> et <span class=\"nc-blue_bg\">examen dentaire</span> régulier recommandés systématiquement. <span>Pas d'antibioprophylaxie systématique</span> avant les gestes à risque (notamment dentaires) sur valve native — sauf antécédent d'EI, <span>prothèse valvulaire</span> ou <span>cardiopathie cyanogène</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 234 — <span>Insuffisance cardiaque</span> · 152 — <span class=\"nc-red_bg\">Endocardite infectieuse</span></em></p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181f4bfbbf6013763e2a0?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Valvulopathies (233)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418128bf18fa6fb1f6969b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Rétrécissement aortique</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181108907dc584bec5884?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance mitrale</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418193ad00c369c741af6e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance aortique</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181308062dedcd73a6d81?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Rétrécissement mitral</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-08-item-233-valvulopathies/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 233</a></li><li><a href=\"https://academic.oup.com/eurheartj/article/46/44/4635/8234488\" target=\"_blank\" rel=\"noopener noreferrer\">ESC/EACTS · Valvulopathies, 2025</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":0}],"astuces":[{"type":"piege","titre":"Raisonner avant le chiffre","contenu":"<div class=\"notion-course\"><p>Interpréter un seuil avec le tableau clinique, le référentiel et les unités ; une complication aiguë impose de réévaluer immédiatement la stratégie.</p></div>"},{"type":"piege","titre":"Source et synthèse","contenu":"<div class=\"notion-course\"><p>Les schémas du collège restent accessibles. Les arbres ATLAS et leurs compléments sont explicitement identifiés et reliés aux objectifs concernés.</p></div>"}],"strategie":{"Démarche diagnostique":"<div class=\"notion-course\"><ul><li>Rechercher les signes de gravité puis préciser la probabilité et le mécanisme.</li><li>Choisir les examens capables de modifier la décision et confronter les résultats à la clinique.</li></ul></div>","Prise en charge":"<div class=\"notion-course\"><ul><li>Adapter la prise en charge à l’urgence, au terrain, aux contre-indications et aux préférences.</li><li>Prévoir surveillance, éducation et réévaluation ; utiliser les arbres reliés au cours.</li></ul></div>"},"liensGlobaux":[{"href":"https://app.notion.com/p/2ad37f85d94181f4bfbbf6013763e2a0?pvs=204","label":"Ton cours Notion ↗"},{"href":"https://www.sfcardio.fr/publication/chapitre-08-item-233-valvulopathies/","label":"CNEC · Item 233 ↗"},{"href":"https://academic.oup.com/eurheartj/article/46/44/4635/8234488","label":"ESC/EACTS · Valvulopathies, 2025 ↗"}],"arbre":{"rootId":"entry","nodes":[{"id":"entry","kind":"decision","label":"Souffle ou symptômes : forme aiguë mal tolérée ?","detail":"<ul><li>Dyspnée, OAP, choc ; IA/IM aiguë possibles malgré souffle discret.</li></ul>","branches":[{"label":"Oui","to":"urgence"},{"label":"Non","to":"echo"}]},{"id":"urgence","kind":"urgent","label":"Échographie et équipe valvulaire urgentes","detail":"<ul><li>Endocardite, dissection, rupture de pilier/cordage ; chirurgie souvent urgente.</li></ul>","branches":[]},{"id":"echo","kind":"decision","label":"ETT : mécanisme, sévérité et retentissement","detail":"<ul><li>ECG/RXT orientent ; ETO ou autre imagerie si nécessaire.</li></ul>","branches":[{"label":"Valvulopathie sévère","to":"severe"},{"label":"Non sévère","to":"suivi"}]},{"id":"severe","kind":"decision","label":"Symptômes ou critères de retentissement ?","detail":"<ul><li>FEVG, dimensions, effort encadré si indiqué, FA/HTP et aorte.</li></ul>","branches":[{"label":"Oui","to":"equipe"},{"label":"Non","to":"surveillance"},{"label":"IM secondaire","to":"optimiser"}]},{"id":"optimiser","kind":"decision","label":"Traitement optimal de l’insuffisance cardiaque","detail":"<ul><li>Puis réévaluer IM et indication de geste.</li></ul>","branches":[{"label":"IM persistante sélectionnée","to":"equipe"}]},{"id":"equipe","kind":"decision","label":"Chirurgie, TAVI ou TEER selon profil","detail":"<ul><li>Durabilité, anatomie, risque, âge et préférence ; recommandations datées.</li></ul>","branches":[{"label":"Suivi après décision","to":"suivi"}]},{"id":"surveillance","kind":"finish","label":"Surveillance spécialisée active","detail":"<ul><li>Ne pas attendre une dysfonction irréversible ; critères d’intervention précoce.</li></ul>","branches":[]},{"id":"suivi","kind":"finish","label":"Suivi clinique/ETT et traitement associé","detail":"<ul><li>IA : traiter notamment HTA ; le médicament ne répare pas une valve sévère.</li></ul>","branches":[]}]},"cards":[{"i":"11c7bf559133","n":233,"o":"233-1","u":"Définition","t":"Connaître la définition de l’insuffisance mitrale (IM), du rétrécissement aortique (RA) et de l’insuffisance aortique (IA)","q":"Quelle est la définition du rétrécissement aortique (RA) ?","a":"<div class=\"notion-course\"><p>Le rétrécissement aortique est un <strong>obstacle à l'éjection du sang du ventricule gauche</strong>, localisé le plus souvent au niveau de la valve aortique.</p></div>"},{"i":"4926c94c216d","n":233,"o":"233-1","u":"Définition","t":"Connaître la définition de l’insuffisance mitrale (IM), du rétrécissement aortique (RA) et de l’insuffisance aortique (IA)","q":"Quelle est la définition de l'insuffisance mitrale (IM) ?","a":"<div class=\"notion-course\"><p>L'insuffisance mitrale est un <strong>défaut d'étanchéité</strong> de la valve mitrale entraînant un <strong>reflux de sang du ventricule gauche vers l'oreillette gauche en systole</strong>.</p></div>"},{"i":"ea37133ba601","n":233,"o":"233-1","u":"Définition","t":"Connaître la définition de l’insuffisance mitrale (IM), du rétrécissement aortique (RA) et de l’insuffisance aortique (IA)","q":"Quelle est la définition de l'insuffisance aortique (IA) ?","a":"<div class=\"notion-course\"><p>L'insuffisance aortique est un <strong>reflux (régurgitation) de sang de l'aorte vers le ventricule gauche en diastole</strong>. La racine aortique comme la valve peuvent être en cause.</p></div>"},{"i":"1aaab1114baa","n":233,"o":"233-3","u":"Etiologies","t":"Connaître les principales étiologies des valvulopathies (IM, RA, IA)","q":"Quelles sont les causes des insuffisances aortiques (IA) avec atteinte de la racine aortique ?","a":"<div class=\"notion-course\"><ul><li><strong><span class=\"nc-red nc-bold\">Dilatation</span> / maladie annulo-ectasiante</strong> (notamment dans la <strong><span class=\"nc-orange_bg\">maladie de Marfan</span></strong>)</li><li><strong><span class=\"nc-red nc-bold\">Dissection aortique</span></strong></li></ul></div>"},{"i":"4dd9eb3a2cc3","n":233,"o":"233-3","u":"Etiologies","t":"Connaître les principales étiologies des valvulopathies (IM, RA, IA)","q":"Quelles sont les étiologies principales du rétrécissement aortique (RA) chez le sujet jeune (< 65-70 ans) ?","a":"<div class=\"notion-course\"><p>Chez le sujet jeune, l'étiologie principale du rétrécissement aortique est la <strong><span class=\"nc-orange_bg nc-bold\">bicuspidie aortique</span></strong>.</p></div>"},{"i":"4ead2d377b99","n":233,"o":"233-3","u":"Etiologies","t":"Connaître les principales étiologies des valvulopathies (IM, RA, IA)","q":"Quelles sont les causes des insuffisances aortiques (IA) avec atteinte valvulaire ?","a":"<div class=\"notion-course\"><ul><li><strong>Endocardite infectieuse</strong></li><li><strong>Rhumatisme Articulaire Aigu</strong> (RAA)</li><li><strong><span class=\"nc-orange_bg nc-bold\">Bicuspidie aortique</span></strong></li><li>IA paraprothétique / intraprothétique</li></ul></div>"},{"i":"677d77ba720f","n":233,"o":"233-3","u":"Etiologies","t":"Connaître les principales étiologies des valvulopathies (IM, RA, IA)","q":"Quelles sont les étiologies de l'insuffisance mitrale (IM) secondaire (fonctionnelle) ?","a":"<div class=\"notion-course\"><ul><li><strong>Dilatation de l'oreillette gauche</strong> (notamment en cas de fibrillation auriculaire)</li><li>Remodelage post-infarctus du ventricule gauche</li><li><strong><span class=\"nc-blue_bg\">Cardiomyopathie</span> dilatée</strong></li></ul></div>"},{"i":"81cebdd984c9","n":233,"o":"233-3","u":"Etiologies","t":"Connaître les principales étiologies des valvulopathies (IM, RA, IA)","q":"Quelle est l'étiologie principale du rétrécissement aortique (RA) chez le sujet âgé (> 65-70 ans) ?","a":"<div class=\"notion-course\"><p>Chez le sujet âgé, l'étiologie principale du rétrécissement aortique est le <strong>RA <span class=\"nc-orange_bg nc-bold\">dégénératif</span></strong> (maladie de Mönckeberg) dû aux dépôts calciques.</p></div>"},{"i":"af618771607e","n":233,"o":"233-3","u":"Etiologies","t":"Connaître les principales étiologies des valvulopathies (IM, RA, IA)","q":"Quelle est l'étiologie la plus fréquente du rétrécissement mitral (RM) ?","a":"<div class=\"notion-course\"><p>L'étiologie la plus fréquente du rétrécissement mitral est le <strong><span class=\"nc-red_bg\">RAA</span> <span class=\"nc-orange_bg\">post-rhumatismal</span></strong> (caractérisé par une <span class=\"nc-yellow_bg\">fusion commissurale</span>).</p></div>"},{"i":"bb2b2ae8143c","n":233,"o":"233-3","u":"Etiologies","t":"Connaître les principales étiologies des valvulopathies (IM, RA, IA)","q":"Quelles sont les étiologies de l'insuffisance mitrale (IM) organique ?","a":"<div class=\"notion-course\"><ul><li><strong>IM <span class=\"nc-red nc-bold\">dystrophique</span></strong> (<span class=\"nc-yellow_bg\">prolapsus</span>, <span class=\"nc-red_bg\">rupture de cordage</span> due à <span class=\"nc-red nc-bold\">dégénérescence myxoïde ou fibroélastique</span>)</li><li><strong>Endocardite infectieuse</strong></li><li><strong>Rhumatisme Articulaire Aigu</strong> (RAA)</li></ul></div>"},{"i":"e62d101bc53f","n":233,"o":"233-3","u":"Etiologies","t":"Connaître les principales étiologies des valvulopathies (IM, RA, IA)","q":"Expliquer la classification de Carpentier pour les insuffisances mitrales de type 2.","a":"<div class=\"notion-course\"><p>Le <strong>Type 2</strong> de la classification de Carpentier correspond à un <strong>mouvement valvulaire exagéré</strong> (hyper-mobilité), typiquement dû à un <strong><span class=\"nc-yellow_bg\">prolapsus</span></strong> ou une <strong><span class=\"nc-red_bg\">rupture de cordage</span></strong>.</p></div>"},{"i":"0b852f05352c","n":233,"o":"233-4","u":"Diagnostic positif","t":"Connaître les signes fonctionnels et l’examen clinique (auscultation) de l’IM, RA et IA","q":"Quels sont les signes fonctionnels de l'Insuffisance Mitrale (IM) ?","a":"<div class=\"notion-course\"><p>En cas d'IM modérée, les signes fonctionnels sont <strong>absents</strong>. En cas d'IM plus sévère, on observe :</p><ul><li>Une <strong><span class=\"nc-blue_bg\">dyspnée d'effort</span></strong> d'installation lente</li><li>Une <strong>asthénie</strong></li><li>Tardivement, un <strong>OAP</strong> (œdème aigu du poumon)</li><li>Une <strong>orthopnée</strong></li><li>Des <strong>palpitations</strong></li></ul></div>"},{"i":"599dbf8c51b3","n":233,"o":"233-4","u":"Diagnostic positif","t":"Connaître les signes fonctionnels et l’examen clinique (auscultation) de l’IM, RA et IA","q":"Décrivez les caractéristiques auscultatoires du souffle de l'Insuffisance Mitrale (IM).","a":"<div class=\"notion-course\"><ul><li><strong>Temps</strong> : <strong><span class=\"nc-blue_bg\">Holosystolique</span></strong>, de forme <strong>rectangulaire</strong>.</li><li><strong>Foyer/Siège</strong> : <strong>Apexo-axillaire</strong>, maximal à la <span class=\"nc-red nc-bold\">pointe</span>.</li><li><strong>Irradiation</strong> : Vers l'<strong><span class=\"nc-blue_bg\">aisselle</span></strong> (vers la base du cœur si prolapsus postérieur).</li><li><strong>Timbre</strong> : <strong><span class=\"nc-blue_bg\">Doux</span></strong>, en « <span class=\"nc-blue_bg\">jet de vapeur</span> » (parfois rude, musical).</li><li><strong>Position d'examen</strong> : <span class=\"nc-pink_bg\">Décubitus latéral gauche</span>.</li><li><strong>Bruits surajoutés</strong> : <span class=\"nc-yellow_bg nc-bold\">Click</span> méso ou télésystolique (en cas de prolapsus).</li><li><strong>Signes de gravité</strong> : B3, éclat de B2 (en cas d'HTAP), <span class=\"nc-red_bg\">roulement mésodiastolique</span>, souffle d'IT fonctionnelle.</li></ul><p>Le B4 traduit une baisse de compliance et nécessite une contraction atriale ; il n’est pas un critère absolu permettant d’exclure une IM associée à une autre cardiopathie.</p></div>"},{"i":"6b5bc3c7ab01","n":233,"o":"233-4","u":"Diagnostic positif","t":"Connaître les signes fonctionnels et l’examen clinique (auscultation) de l’IM, RA et IA","q":"Quels sont les signes fonctionnels de l'Insuffisance Aortique (IA) ?","a":"<div class=\"notion-course\"><p>L'IA est souvent <strong>asymptomatique</strong>. Les signes fonctionnels comprennent :</p><ul><li><strong><span class=\"nc-blue_bg\">Dyspnée d'effort</span></strong> (cotée selon la classification NYHA)</li><li><strong>Angor</strong> (rare, et généralement présent en cas d'IA massive)</li><li><strong><span class=\"nc-blue_bg\">Asthénie</span></strong></li></ul><p>Les signes cliniques au repos sont rares, tardifs et de mauvais pronostic.</p></div>"},{"i":"837f2af9477f","n":233,"o":"233-4","u":"Diagnostic positif","t":"Connaître les signes fonctionnels et l’examen clinique (auscultation) de l’IM, RA et IA","q":"Quels sont les signes fonctionnels de la Rétrécissement Aortique (RA) et leur signification pronostique ?","a":"<div class=\"notion-course\"><p>Le RA est <strong>longtemps <span class=\"nc-yellow_bg\">asymptomatique</span></strong>. À la phase symptomatique, il se manifeste par la <strong>triade</strong> :</p><ul><li><strong>Angor d'effort</strong></li><li><strong><span class=\"nc-blue_bg\">Syncope d'effort</span></strong></li><li><strong><span class=\"nc-blue_bg\">Dyspnée d'effort</span></strong></li></ul><p>L'apparition de ces signes est de <strong>mauvais pronostic</strong>.</p></div>"},{"i":"b13035fd8044","n":233,"o":"233-4","u":"Diagnostic positif","t":"Connaître les signes fonctionnels et l’examen clinique (auscultation) de l’IM, RA et IA","q":"Décrivez les caractéristiques auscultatoires du souffle de l'Insuffisance Aortique (IA).","a":"<div class=\"notion-course\"><ul><li><strong>Temps</strong> : <strong><span class=\"nc-blue nc-bold\">Proto-mésodiastolique</span></strong>, de forme <strong><span class=\"nc-blue nc-bold\">decrescendo</span></strong> (<span class=\"nc-purple_bg\">triangulaire</span>).</li><li><strong>Foyer/Siège</strong> : Foyer <strong>aortique</strong> (2<sup>e</sup> EIC droit).</li><li><strong>Irradiation</strong> : Bord gauche du sternum.</li><li><strong>Timbre</strong> : <strong>Doux</strong>, <strong>humé</strong>, <strong>aspiratif</strong>.</li><li><strong>Position d'examen</strong> : Assis penché en avant, bras levé.</li><li><strong>Bruits surajoutés</strong> : <strong><span class=\"nc-red nc-bold\">Pistol shot mésosystolique</span></strong>, click protosystolique.</li><li><strong>Signes de gravité</strong> : <span class=\"nc-red_bg\">Souffle holodiastolique</span>, B3, <span class=\"nc-red_bg\">roulement de Flint apexien</span> (ne pas confondre avec le <span class=\"nc-red_bg\">roulement mésodiastolique</span> de l'IM).</li></ul></div>"},{"i":"e3ae7d46b07a","n":233,"o":"233-4","u":"Diagnostic positif","t":"Connaître les signes fonctionnels et l’examen clinique (auscultation) de l’IM, RA et IA","q":"Décrivez les caractéristiques auscultatoires du souffle de Rétrécissement Aortique (RA).","a":"<div class=\"notion-course\"><ul><li><strong>Temps</strong> : <strong><span class=\"nc-blue_bg\">Mésosystolique</span></strong>, de forme <strong><span class=\"nc-blue_bg\">losangique</span></strong>.</li><li><strong>Foyer/Siège</strong> : Foyer <strong>aortique</strong> (2<sup>e</sup> EIC droit).</li><li><strong>Irradiation</strong> : Vers les <strong>vaisseaux du cou (carotides)</strong>.</li><li><strong>Timbre</strong> : <strong>Rude</strong>, <strong><span class=\"nc-blue_bg\">râpeux</span></strong>.</li><li><strong>Position d'examen</strong> : Assis penché en avant, en expiration.</li><li><strong>Bruits surajoutés</strong> : <strong>B4</strong> (galop présystolique).</li><li><strong>Signe de gravité</strong> : <strong><span class=\"nc-red nc-bold\">Abolition du B2</span></strong> (en cas de RA serré calcifié), B3 de galop, souffle inaudible si bas débit.</li></ul></div>"},{"i":"00e6d860d91f","n":233,"o":"233-6","u":"Examens complémentaires","t":"Connaître la valeur primordiale de l’échocardiographie dans l’IM, l’IA et le RA","q":"Comment évalue-t-on un rétrécissement aortique (RA) dit « à bas débit, bas gradient » avec une fraction d'éjection ventriculaire gauche (FEVG) basse ?","a":"<div class=\"notion-course\"><ul><li>RA bas débit/bas gradient : examiner volume d’éjection indexé, FEVG, PA et erreurs de mesure ; dobutamine dans certaines formes à FEVG réduite, score calcique valvulaire au scanner selon contexte. Un bas débit peut exister malgré une FEVG préservée.</li></ul></div>"},{"i":"2567a87c07ee","n":233,"o":"233-6","u":"Examens complémentaires","t":"Connaître la valeur primordiale de l’échocardiographie dans l’IM, l’IA et le RA","q":"Quels sont les critères échocardiographiques permettant de diagnostiquer positivement un rétrécissement aortique (RA), une insuffisance mitrale (IM) et une insuffisance aortique (IA) ?","a":"<div class=\"notion-course\"><ul><li>Pour le <strong>rétrécissement aortique (RA)</strong> : <ul><li>Valve calcifiée.</li><li>Ouverture des sigmoïdes diminuée.</li><li><strong>Augmentation du gradient systolique VG-aorte</strong>.</li></ul></li><li>Pour l'<strong>insuffisance mitrale (IM)</strong> : <ul><li><strong>Régurgitation systolique VG → OG</strong> visible au Doppler.</li></ul></li><li>Pour l'<strong>insuffisance aortique (IA)</strong> : <ul><li><strong>Régurgitation diastolique Aorte → VG</strong> visible au Doppler.</li></ul></li></ul></div>"},{"i":"36b5d76a8f44","n":233,"o":"233-6","u":"Examens complémentaires","t":"Connaître la valeur primordiale de l’échocardiographie dans l’IM, l’IA et le RA","q":"Quelle est la place de l'échocardiographie dans le diagnostic et l'évaluation des valvulopathies, notamment l'insuffisance mitrale (IM), l'insuffisance aortique (IA) et le rétrécissement aortique (RA) ?","a":"<div class=\"notion-course\"><ul><li>L’ETT Doppler est l’examen central : valve et mécanisme, sévérité intégrée, ventricules, oreillettes, pressions pulmonaires et aorte. L’ETO complète une mauvaise fenêtre, une suspicion d’endocardite ou la planification d’un geste.</li></ul></div>"},{"i":"93106ac927d4","n":233,"o":"233-6","u":"Examens complémentaires","t":"Connaître la valeur primordiale de l’échocardiographie dans l’IM, l’IA et le RA","q":"Quel est le retentissement des valvulopathies sur le cœur et le pronostic, visualisable à l’échocardiographie ?","a":"<div class=\"notion-course\"><ul><li>Pour le <strong>rétrécissement aortique (RA)</strong> : <ul><li><strong><span class=\"nc-blue_bg\">Hypertrophie ventriculaire gauche</span> (HVG)</strong>.</li><li>Dilatation du VG.</li><li>Fraction d'éjection ventriculaire gauche (FEVG) potentiellement altérée.</li><li>Hypertension artérielle pulmonaire (HTAP) tardive.</li></ul></li><li>Pour l'<strong>insuffisance mitrale (IM)</strong> : <ul><li>FEVG altérée.</li><li>Dilatation du VG et de l'OG.</li><li>HTAP.</li></ul></li><li>Pour l'<strong>insuffisance aortique (IA)</strong> : <ul><li>FEVG diminuée.</li><li>Dilatation du VG.</li><li>HTAP.</li></ul></li></ul></div>"},{"i":"d59bcd4e62d2","n":233,"o":"233-6","u":"Examens complémentaires","t":"Connaître la valeur primordiale de l’échocardiographie dans l’IM, l’IA et le RA","q":"Comment évalue-t-on la sévérité d'un rétrécissement aortique (RA), d'une insuffisance mitrale (IM) et d'une insuffisance aortique (IA) par échocardiographie ?","a":"<div class=\"notion-course\"><ul><li>RA sévère à haut gradient : Vmax ≥ 4 m/s, gradient moyen ≥ 40 mmHg, surface généralement ≤ 1 cm² (≤ 0,6 cm²/m² indexée). Vérifier la concordance et les mesures ; un petit orifice avec faible gradient n’est pas automatiquement un RA sévère.</li><li>IM : évaluation multiparamétrique (morphologie, vena contracta, flux, volume et surface régurgitants, retentissement). Repères classiques d’IM primaire sévère : surface régurgitante ≥ 40 mm², <span class=\"nc-blue_bg\">volume régurgité</span> ≥ 60 mL ; des seuils plus faibles peuvent être pertinents dans l’IM secondaire à bas débit. Ne pas appliquer 30 mm²/45 mL à toute IM.</li><li>IA : mécanisme valvulaire ou aortique, jet, vena contracta, reflux <span class=\"nc-red nc-bold\">holodiastolique</span> dans l’aorte descendante et quantification intégrée ; mesurer VG, FEVG et aorte.</li></ul></div>"},{"i":"b64d79d7e6f1","n":233,"o":"233-2","u":"Eléments physiopathologiques","t":"Connaître les mécanismes et conséquences physiopathologiques de l’IM, l’IA et du RA","q":"Quels sont les points clés concernant les mécanismes et conséquences physiopathologiques de l’IM, l’IA et du RA ?","a":"<div class=\"notion-course\"><ul><li>Le mécanisme d'adaptation du VG dépend de la nature de la surcharge imposée : surcharge de <strong>pression</strong> (RA) ou surcharge de <strong>volume</strong> (IA, IM). C'est ce qui détermine le type d'hypertrophie du VG.</li><li><strong>RA — détail.</strong> Le rétrécissement crée un <span><span class=\"nc-yellow_bg\"><span class=\"nc-yellow_bg\">gradient de pression VG–aorte</span></span></span> ; le VG s'hypertrophie pour normaliser les contraintes pariétales (loi de Laplace) et garde longtemps une <span>FEVG normale</span>. À la phase <span class=\"nc-red nc-bold\"><span class=\"nc-red nc-bold\">symptomatique</span></span> : ↓ compliance → <span><span class=\"nc-blue_bg\"><span class=\"nc-blue_bg\">dyspnée</span></span></span> (<span class=\"nc-blue nc-bold\"><span class=\"nc-blue nc-bold\">congestion pulmonaire</span></span>), ↑ consommation en O₂ → <span>angor</span>, dilatation et ↓ débit → <span><span class=\"nc-blue_bg\"><span class=\"nc-blue_bg\">syncope d'effort</span></span></span>. La <span>perte de la systole atriale lors d'un passage en FA</span> est en général mal tolérée (poussée d'IC).</li><li><strong>IA — détail.</strong> En amont : surcharge volumétrique (régurgitation <span class=\"nc-blue_bg\"><span class=\"nc-blue_bg\">diastolique</span></span>) + barométrique (↑ VES dans l'aorte). En aval : ↑ PAS et ↓ <span class=\"nc-yellow_bg\"><span class=\"nc-yellow_bg\">PAD</span></span> → <span>↑ pression artérielle différentielle</span> (hyperpulsatilité) ; la baisse de la <span class=\"nc-yellow_bg\"><span class=\"nc-yellow_bg\">PAD</span></span> <span class=\"nc-blue_bg\"><span class=\"nc-blue_bg\">diastolique</span></span> compromet la perfusion coronaire (<span><span class=\"nc-red nc-bold\"><span class=\"nc-red nc-bold\">vol coronarien</span></span></span><span class=\"nc-red nc-bold\"><span class=\"nc-red nc-bold\"> si IA sévère</span></span>). L'<span>IA aiguë</span> impose une surcharge volumétrique brutale à un VG non dilaté → élévation brutale des pressions → <span><span class=\"nc-red_bg\"><span class=\"nc-red_bg\">OAP</span></span></span>.</li><li><strong>IM — détail.</strong> Le <span class=\"nc-red_bg\"><span class=\"nc-red_bg\">VES est divisé en volume antérograde (vers l'aorte) et rétrograde (vers l'OG)</span></span> ; la compensation passe par l'activation du SRAA et du système sympathique. La <span class=\"nc-red nc-bold\"><span class=\"nc-red nc-bold\">dilatation</span></span> de l'OG maintient une pression intra-atriale quasi normale mais favorise les <span>troubles du rythme atrial</span>. L'<span>IM aiguë</span> survient sur une OG non encore dilatée → <span>HTP immédiate</span>.</li></ul></div>"},{"i":"d986cec58373","n":233,"o":"233-5","u":"Examens complémentaires","t":"Connaître l’intérêt de l’électrocardiogramme (ECG), de la radiographie thoracique, de l’épreuve d’effort dans les valvulopathies","q":"Quels sont les points clés concernant l’intérêt de l’électrocardiogramme (ECG), de la radiographie thoracique, de l’épreuve d’effort dans les valvulopathies ?","a":"<div class=\"notion-course\"><ul><li>L'<span>ECG</span> et la <span>radiographie thoracique</span> sont des examens de <strong><span class=\"nc-red nc-bold\"><span class=\"nc-red nc-bold\">retentissement</span></span></strong> : ils ne font pas le diagnostic (c'est l'<span>échographie</span>) mais évaluent l'<span>évolution</span>. L'<span>épreuve d'effort</span> a une place très ciblée.</li><li><strong><span>Épreuve d'effort</span> — points clés.</strong> Dans le RA serré asymptomatique : recherche d'une augmentation inadéquate ou d'une baisse de la PA à l'effort, et démasquage de <span class=\"nc-red nc-bold\"><span class=\"nc-red nc-bold\">symptômes</span></span>. Dans l'IA : <span>non indiquée selon le LiSA</span>, mais peut aider à la décision en appréciant la tolérance fonctionnelle.</li><li><em>📎 Items liés : 232 — <span><span class=\"nc-blue_bg\"><span class=\"nc-blue_bg\">Fibrillation</span></span></span><span class=\"nc-blue_bg\"><span class=\"nc-blue_bg\"> atriale</span></span></em></li></ul></div>"},{"i":"1b3f5cdd21d7","n":233,"o":"233-7","u":"Suivi et/ou pronostic","t":"Connaître les évolutions et complications de l’IM, du RA et de l’IA","q":"Quels sont les points clés concernant les évolutions et complications de l’IM, du RA et de l’IA ?","a":"<div class=\"notion-course\"><ul><li>Toutes les valvulopathies gauches chroniques sont longtemps bien tolérées ; <strong>l'apparition de <span class=\"nc-red nc-bold\"><span class=\"nc-red nc-bold\">symptômes</span></span> signe un tournant pronostique</strong>. Les formes aiguës sont d'emblée des urgences.</li><li><em>📎 Items liés : 152 — <span class=\"nc-red_bg\"><span class=\"nc-red_bg\">Endocardite infectieuse</span></span> · 232 — <span><span class=\"nc-blue_bg\"><span class=\"nc-blue_bg\">Fibrillation</span></span></span><span class=\"nc-blue_bg\"><span class=\"nc-blue_bg\"> atriale</span></span> · 234 — <span>Insuffisance cardiaque</span> · 332 — Etat de <span>choc</span></em></li></ul></div>"},{"i":"e67e5fa10244","n":233,"o":"233-8","u":"Prise en charge","t":"Connaître les principes du traitement chirurgical de l’IM, du RA et de l’IA","q":"Quels sont les points clés concernant les principes du traitement chirurgical de l’IM, du RA et de l’IA ?","a":"<div class=\"notion-course\"><ul><li>Le traitement curatif d'une valvulopathie est mécanique (chirurgical ou percutané) : il n'existe pas de <span class=\"nc-pink_bg\"><span class=\"nc-pink_bg\">traitement médical</span></span> capable de corriger la <span>lésion</span>. Principes par valvulopathie :</li><li>Rechercher et traiter les foyers infectieux, notamment dentaires, avant une intervention programmée ; les examens ORL, respiratoires et vasculaires sont guidés par le contexte plutôt qu’imposés à tous.</li><li><em>📎 Items liés : 153 — <span>Surveillance</span> valve et prothèse vasculaire</em></li></ul></div>"},{"i":"72fffebc9815","n":233,"o":"233-9","u":"Prise en charge","t":"Connaître le principe des traitements percutanés de l’IM, du RA","q":"Quels sont les points clés concernant le principe des traitements percutanés de l’IM, du RA ?","a":"<div class=\"notion-course\"><ul><li>Les traitements percutanés évitent la sternotomie et la circulation extracorporelle : ils s'adressent surtout aux patients âgés ou à risque chirurgical.</li><li><em>📎 Items liés : 153 — <span>Surveillance</span> valve et prothèse vasculaire</em></li></ul></div>"},{"i":"2e5c461cae0e","n":233,"o":"233-10","u":"Prise en charge","t":"Connaître les principales indications de traitement chirurgical de l’IM, du RA et de l’IA","q":"Quels sont les points clés concernant les principales indications de traitement chirurgical de l’IM, du RA et de l’IA ?","a":"<div class=\"notion-course\"><ul><li>Décision en équipe valvulaire : sévérité confirmée, symptômes, fonction/dimensions ventriculaires, risque, anatomie, espérance de vie et préférence du patient.</li><li>RA <span class=\"nc-yellow_bg\">sévère symptomatique</span> : <span class=\"nc-pink_bg\">remplacement valvulaire</span> sauf absence de bénéfice attendu ; la voie dépend de la Heart Team. Si apparemment <span class=\"nc-yellow_bg\">asymptomatique</span> : test d’effort encadré si indiqué, FEVG, progression, sévérité et marqueurs pronostiques ; certaines situations justifient une intervention précoce.</li><li>IA sévère : <span class=\"nc-red nc-bold\">symptômes</span> ou <span class=\"nc-red nc-bold\">retentissement</span> VG justifient l’intervention. Repères classiques chez l’<span class=\"nc-yellow_bg\">asymptomatique</span> : <span class=\"nc-red nc-bold\">FEVG ≤ 50 %</span>, diamètre télésystolique <span class=\"nc-red nc-bold\">&gt; 50 mm</span> ou <span class=\"nc-red nc-bold\">&gt; 25 mm/m²</span>. Des critères plus précoces peuvent être discutés dans les recommandations récentes, surtout à faible risque opératoire.</li><li>IM primaire sévère : réparation durable privilégiée si possible. Repères de dysfonction : FEVG ≤ 60 % ou diamètre télésystolique ≥ 40 mm ; une <span class=\"nc-red nc-bold\">rupture de cordage</span> n’est pas nécessaire pour utiliser ces seuils. FA, hypertension pulmonaire et <span class=\"nc-red nc-bold\">dilatation</span> de l’OG peuvent également conduire à une intervention sélectionnée.</li></ul></div>"},{"i":"880b6255a502","n":233,"o":"233-11","u":"Prise en charge","t":"Connaître les principales indications du traitement percutané du RA et de l’IM","q":"Quels sont les points clés concernant les principales indications du traitement percutané du RA et de l’IM ?","a":"<div class=\"notion-course\"><ul><li>TAVI ou <span class=\"nc-pink_bg\">chirurgie</span> : décision partagée en Heart Team tenant compte de l’âge, de la durabilité, de l’anatomie valvulaire/aortique et vasculaire, des coronaires et des gestes associés.</li><li>Actualisation ESC/EACTS 2025 : TAVI recommandé à partir de 70 ans pour une sténose aortique tricuspide avec anatomie adaptée ; chirurgie privilégiée chez le patient plus jeune à faible risque. Les autres cas sont individualisés. Le seuil de 75 ans correspond à des recommandations antérieures.</li><li>Réparation mitrale bord à bord (TEER) : IM primaire <span class=\"nc-yellow_bg\">sévère symptomatique</span> à haut risque chirurgical avec anatomie favorable, ou IM secondaire sélectionnée malgré traitement optimal ; vérifier les critères et le bénéfice attendu.</li><li>Commissurotomie mitrale percutanée : RM rhumatismal sélectionné, valve adaptée, sans thrombus atrial ni IM significative ; l’ETO est importante avant le geste.</li></ul></div>"},{"i":"1a6200624636","n":233,"o":"233-12","u":"Prise en charge","t":"Connaître les modalités du traitement médical de l’IA","q":"Quels sont les points clés concernant les modalités du traitement médical de l’IA ?","a":"<div class=\"notion-course\"><ul><li>Le <span class=\"nc-pink_bg\"><span class=\"nc-pink_bg\">traitement médical</span></span> de l'IA se limite à des situations précises :</li><li><strong>IA sévère compliquée d'IC congestive :</strong> <span class=\"nc-pink_bg\"><span class=\"nc-pink_bg\">traitement médical</span></span> (<span>diurétiques</span>, éventuellement <span>IEC</span>) <em>dans l'attente de la <span>chirurgie</span></em> — la résolution des signes d'IC sous traitement ne doit pas faire repousser la chirurgie.</li><li><strong><span>Syndrome de <span class=\"nc-yellow_bg\"><span class=\"nc-yellow_bg\">Marfan</span></span></span> / <span class=\"nc-red nc-bold\"><span class=\"nc-red nc-bold\">dilatation</span></span> de l'aorte :</strong> <span><span class=\"nc-pink nc-bold\"><span class=\"nc-pink nc-bold\">bêtabloquants</span></span></span> = traitement validé pour protéger l'aorte ; <span><span class=\"nc-pink nc-bold\"><span class=\"nc-pink nc-bold\">ARA2</span></span></span> uniquement en cas d'<span>intolérance</span> aux <span><span class=\"nc-pink nc-bold\"><span class=\"nc-pink nc-bold\">bêtabloquants</span></span></span>.</li><li><strong>Activité physique :</strong> sport de compétition <span>contre-indiqué si IA sévère</span> ; sport de loisir en endurance encouragé à un niveau modéré.</li></ul></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/2ad37f85d94181f4bfbbf6013763e2a0?pvs=204","reviewedAt":"2026-10-15","note":"Cours, cartes et arbres relus. Couleurs des passages Notion correspondants ; références et compléments identifiés dans chaque objectif."}};
